select
    'Synthea synthetic patients (portfolio project)'::text  as cdm_source_name,
    'SYNTHEA_RWE'::text                                     as cdm_source_abbreviation,
    'synthea-omop-rag'::text                                as cdm_holder,
    'SYNTHETIC DATA ONLY. Generated by Synthea; supports no clinical conclusions.'::text
                                                            as source_description,
    'https://github.com/synthetichealth/synthea'::text      as source_documentation_reference,
    'docs/decisions/'::text                                 as cdm_etl_reference,
    '{{ var("data_end_date") }}'::date                      as source_release_date,
    current_date                                            as cdm_release_date,
    'v5.4'::text                                            as cdm_version,
    coalesce((select concept_id from {{ source('vocab', 'concept') }}
              where vocabulary_id = 'CDM' and concept_code = 'CDM v5.4'), 0)::integer
                                                            as cdm_version_concept_id,
    (select vocabulary_version from {{ source('vocab', 'vocabulary') }}
     where vocabulary_id = 'None')::text                    as vocabulary_version
